module Controller_8_29h (input  x, y, E, F, clock, reset_b);  parameter  S_0 = 3'b000, S_1 = 3'b001, S_2 = 3'b010,       S_3 = 3'b011, S_4 = 3'b100, S_5 = 3'b101, S_6 = 3'b110, S_7 = 3'b111;  reg [2: 0 ] state, next_state;  always @ (posedge clock, negedge reset_b)      if (!reset_b) state <= S_0; else state <= next_state; always @ (state, x, y, E, F) begin    case (state)      S_0:				if (x) next_state = S_1;						else next_state =  y ? S_2: S_0;      S_1: 				next_state = S_2;        S_2:				if (F) next_state = S_3; else next_state = S_4;      S_3, S_5, S_7:	next_state = S_0;      S_4: 				if (E) next_state = S_5; else next_state = S_6;      S_6:				next_state = S_7;      default: 			next_state = S_0;    endcase  endendmodule// Test plan: Exercise all paths of the ASM chartmodule t_Controller_8_29h ();  reg  x, y, E, F, clock, reset_b;  Controller_8_29h M0 (x, y, E, F, clock, reset_b);   initial #500 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial begin end  initial fork    reset_b = 0; #2 reset_b = 1;    #20 begin x = 1; y = 1; E = 1; F = 1; end	// Path: S_0, S_1, S_2, S_34    #80 reset_b = 0; #92 reset_b = 1;     #90 begin x = 1; y = 1; E = 1; F = 0; end    #150 reset_b = 0;     #152 reset_b = 1;    #150 begin x = 1; y = 1; E = 0; F = 0; end	// Path: S_0, S_1, S_2, S_4, S_5    #200 reset_b = 0;     #202 reset_b = 1;    #190 begin x = 1; y = 1; E = 0; F = 0; end	// Path: S_0, S_1, S_2, S_4, S_6, S_7    #250 reset_b = 0;     #252 reset_b = 1;    #240 begin x = 0; y = 0; E = 0; F = 0; end	// Path: S_0    #290 reset_b = 0;     #292 reset_b = 1;    #280 begin x = 0; y = 1; E = 0; F = 0; end	// Path: S_0, S_2, S_4, S_6, S_7    #360 reset_b = 0;     #362 reset_b = 1;    #350 begin x = 0; y = 1; E = 1; F = 0; end	// Path: S_0, S_2, S_4, S_5    #420 reset_b = 0;     #422 reset_b = 1;    #410 begin x = 0; y = 1; E = 0; F = 1; end	// Path: S_0, S_2, S_3  joinendmodule